"""Replay double of `runlog.RunWriter`: keeps what it is given, returns what the run recorded.

`checkpoint(pct, ...)` returns the recorded checkpoint at that percentage (`KeyError` for one
the run never wrote); `close(status, failure)` returns the recorded record with that status and
failure. Nothing touches the disk.
"""

from collections.abc import Mapping
from dataclasses import dataclass, field, replace
from typing import Any

from rllab.core import EpisodeResult
from rllab.runlog import Checkpoint, EvalPoint, Failure, RunRecord


@dataclass
class ReplayRunWriter:
    recorded_checkpoints: dict[int, Checkpoint]
    recorded_record: RunRecord
    episodes: list[EpisodeResult] = field(default_factory=list)
    evals: list[EvalPoint] = field(default_factory=list)
    states: dict[int, Mapping[str, dict[str, object]]] = field(default_factory=dict)

    def episode(self, result: EpisodeResult) -> None:
        self.episodes.append(result)

    def eval(self, point: EvalPoint) -> None:
        self.evals.append(point)

    def checkpoint(self, pct: int, step: int, state: Mapping[str, dict[str, object]]) -> Checkpoint:
        self.states[pct] = state
        return self.recorded_checkpoints[pct]

    def close(self, status: str, failure: Failure | None = None) -> RunRecord:
        return replace(self.recorded_record, status=status, failure=failure)


def build(kit: Any, recording: dict[str, Any]) -> ReplayRunWriter:
    checkpoints = kit.decode(list[Checkpoint], recording["checkpoints"])
    record = kit.decode(RunRecord, recording["record"])
    return ReplayRunWriter({c.pct: c for c in checkpoints}, record)

